# model_new.py
import torch
import torch.nn as nn
from torch.utils import cpp_extension
import os

# ----------------------------------------------------------------------
# CUDA kernel implementing fp16 1‑D max‑pooling
# ----------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

#ifndef CHECK_CUDA
#define CHECK_CUDA(x) TORCH_CHECK(x.is_cuda(), #x " must be a CUDA tensor")
#endif
#ifndef CHECK_CONTIGUOUS
#define CHECK_CONTIGUOUS(x) TORCH_CHECK(x.is_contiguous(), #x " must be contiguous")
#endif
#ifndef CHECK_INPUT
#define CHECK_INPUT(x) CHECK_CUDA(x); CHECK_CONTIGUOUS(x)
#endif

// One thread = one output element
template <int BLOCK_SIZE>
__global__ void maxpool1d_fp16_kernel(
    const __half* __restrict__ A,
    __half* __restrict__ O,
    const int B,
    const int C,
    const int L,
    const int L_out,
    const int kernel_size,
    const int stride,
    const int padding,
    const int dilation)
{
    const int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const int total = B * C * L_out;
    if (tid >= total) return;

    // decode indices
    const int o = tid % L_out;
    const int bc = tid / L_out;
    const int b = bc / C;
    const int c = bc % C;

    const int start = o * stride - padding;
    __half max_val = __float2half(-65504.0f);   // smallest fp16

    for (int k = 0; k < kernel_size; ++k) {
        const int idx = start + k * dilation;
        if (idx >= 0 && idx < L) {
            const __half cur = A[(b * C + c) * L + idx];
            max_val = __hgt(cur, max_val) ? cur : max_val;
        }
    }
    O[(b * C + c) * L_out + o] = max_val;
}

// Wrapper called from Python
void maxpool1d_fp16(
    torch::Tensor input,
    torch::Tensor output,
    const int kernel_size,
    const int stride,
    const int padding,
    const int dilation)
{
    CHECK_INPUT(input);
    CHECK_INPUT(output);
    const int B = input.size(0);
    const int C = input.size(1);
    const int L = input.size(2);
    const int L_out = output.size(2);

    const int total = B * C * L_out;
    const int BLOCK_SIZE = 128;
    const int grid = (total + BLOCK_SIZE - 1) / BLOCK_SIZE;

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(input.scalar_type(), "maxpool1d_fp16", ([&] {
        maxpool1d_fp16_kernel<BLOCK_SIZE><<<grid, BLOCK_SIZE>>>(
            reinterpret_cast<const __half*>(input.data_ptr<scalar_t>()),
            reinterpret_cast<__half*>(output.data_ptr<scalar_t>()),
            B, C, L, L_out,
            kernel_size, stride, padding, dilation);
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(std::string("CUDA kernel failed: ") + cudaGetErrorString(err));
    }
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
  m.def("maxpool1d_fp16", &maxpool1d_fp16, "FP16 1D MaxPool (CUDA)");
}
'''

