_ext_file = os.path.join(_ext_path, 'maxpool1d_fp16.cpp')
with open(_ext_file, 'w') as f:
    f.write(cuda_source)

maxpool1d_cuda = cpp_extension.load(
    name='maxpool1d_fp16',
    sources=[_ext_file],
    verbose=False,
    extra_cflags=['-O3'],
    extra_cuda_cflags=['-O3', '--use_fast_math'],
    build_directory=_ext_path,
)

# ----------------------------------------------------------------------
# ModelNew – drop‑in replacement for the reference Model
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model.
    Uses a custom CUDA kernel for fp16 1‑D max‑pooling.
    """
    def __init__(
        self,
        kernel_size: int,
        stride: int = None,
        padding: int = 0,
        dilation: int = 1,
        return_indices: bool = False,
    ):
        super().__init__()
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size
        self.padding = padding
        self.dilation = dilation
        self.return_indices = return_indices
        if self.return_indices:
            raise NotImplementedError(
                "return_indices=True is not supported by the custom kernel."
            )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure input is fp16 on CUDA
        x = x.to(dtype=torch.float16, device="cuda")
        B, C, L = x.shape

        # Compute output length using the same formula as nn.MaxPool1d
        L_out = (L + 2 * self.padding -
                 self.dilation * (self.kernel_size - 1) - 1) // self.stride + 1

        out = torch.empty(B, C, L_out, dtype=torch.float16, device="cuda")

        # Call the compiled CUDA kernel
        maxpool1d_cuda.maxpool1d_fp16(
            x,
            out,
            self.kernel_size,
            self.stride,
            self.padding,
            self.dilation,
        )
        return out


